"""Render the beginner-first, normalized interactive dashboard from the trained bundle."""
from pathlib import Path
import json, html
import pandas as pd

BASE = Path(__file__).resolve().parent
B = json.loads((BASE / "simulator_bundle.json").read_text(encoding="utf-8"))
catalog = pd.read_csv(BASE / "PARAMETER_31_TO_9.csv")
metrics = pd.read_csv(BASE / "MULTIOUTPUT_MODEL_METRICS.csv")
lot_diag = pd.read_csv(BASE / "LOT_BETWEEN_WITHIN_DIAGNOSTICS.csv")

