param_cards = []
for i,p in enumerate(B["parameters"]):
    u = UI[p["channel"]]
    median_norm = (p["median"]-p["q10"])/(p["q90"]-p["q10"])
    param_cards.append(f"""
    <article class="param-card" data-param="{i}">
      <div class="param-top"><span class="param-icon">{u['icon']}</span><div><small>{html.escape(u['where'])}</small><h3>{html.escape(p['label'])}</h3></div><button class="info-btn" data-info="{i}" aria-expanded="false" aria-label="{html.escape(p['label'])} 설명 열기">?</button></div>
      <p class="param-short">{html.escape(u['short'])}</p>
      <div class="dial-row"><div class="dial" id="dial{i}"><strong id="n{i}">{median_norm:.2f}</strong><span>정규화</span></div><div class="slider-wrap"><div class="scale"><span>0 낮음</span><span>1 높음</span></div><input id="p{i}" type="range" min="0" max="1" step="0.005" value="{median_norm:.6f}" aria-label="{html.escape(p['label'])} 정규화 값"></div></div>
      <div class="param-detail" id="info{i}" hidden>
        <div class="raw-box"><b>실제 관측 범위</b><span>0 = {p['q10']:.6g}</span><span>중앙 = {p['median']:.6g}</span><span>1 = {p['q90']:.6g}</span></div>
        <div class="meaning low"><b>0에 가까우면</b><p>{html.escape(u['low'])}</p></div>
        <div class="meaning high"><b>1에 가까우면</b><p>{html.escape(u['high'])}</p></div>
        <p class="role"><b>장비에서 하는 일:</b> {html.escape(u['role'])}</p>
      </div>
    </article>""")

catalog_html = ''.join(
    f"<div class='sensor {'keep' if r.decision=='유지' else ('merge' if r.decision=='대표로 통합' else 'drop')}'><span>{html.escape(str(r.category))} · {html.escape(str(r.decision))}</span><b>{html.escape(str(r.plain_meaning))}</b><code>{html.escape(str(r.channel))}</code><small>{html.escape(str(r.reason))}</small></div>"
    for _,r in catalog.iterrows()
)

target_order=["si_mean","si_cv","edge_center","oxide_mean","selectivity","si_range"]
output_cards=[]
for t in target_order:
    m=B["targets"][t]
    quality="good" if m["reliability"]=="높음" else ("mid" if m["reliability"]=="중간" else "bad")
    output_cards.append(f"""<article class="out" data-out="{t}"><div class="out-head"><span>{html.escape(m['label'])}</span><button class="quality {quality}" data-quality="{quality}">{html.escape(m['reliability'])}</button></div><div class="value"></div><div class="range"><span></span></div><div class="meta"></div><p>{html.escape(m['description'])}</p></article>""")

metric_rows=''.join(
    f"<tr><td>{html.escape(B['targets'][r.target]['label'])}</td><td>{r.lolo_mae:.3f}</td><td>{r.lolo_rmse:.3f}</td><td>{r.lolo_r2:.3f}</td><td>{html.escape(B['targets'][r.target]['reliability'])}</td></tr>"
    for _,r in metrics.iterrows()
)
si_diag=lot_diag.loc[lot_diag.target.eq('si_mean')].iloc[0]
lot_diagnostic_html=f"""<div class="surface"><h2>모델이 로트 평균만 맞힌 것인가?</h2><div class="stats"><div class="stat"><span>Si 깊이 전체 변동 중</span><b>{si_diag.within_variance_fraction*100:.1f}%</b><small>같은 로트 안의 웨이퍼별 변화</small></div><div class="stat"><span>로트 사이 평균 차이</span><b>{si_diag.between_variance_fraction*100:.1f}%</b><small>전체 변동에서 차지하는 비율</small></div><div class="stat"><span>로트 평균 제거 후 R²</span><b>{si_diag.within_centered_r2:.3f}</b><small>로트 내 변화 예측력</small></div><div class="stat"><span>로트 평균만 답할 때 MAE</span><b>{si_diag.oracle_actual_lot_mean_mae:.3f}</b><small>현재 모델 MAE {si_diag.model_mae:.3f} µm</small></div></div><p>실제 테스트 로트의 평균 정답을 미리 알려주는 유리한 조건에서도, 모든 웨이퍼에 그 평균만 답하면 오차가 {si_diag.oracle_actual_lot_mean_mae:.3f} µm입니다. 현재 모델은 {si_diag.model_mae:.3f} µm이므로 웨이퍼별 변화도 추적하고 있습니다. 다만 시간파형 전체를 그대로 쓰는 것이 아니라 평균·단계별 평균·변동폭·후반−초반으로 요약합니다.</p></div>"""

payload=json.dumps({"bundle":B},ensure_ascii=False,separators=(",",":"))

