JS=r"""
const B=JSON.parse(document.getElementById('payload').textContent).bundle;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const fmt=(v,d=3)=>Number(v).toFixed(d), clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function rawValue(i){const p=B.parameters[i],n=+$('#p'+i).value;return p.q10+n*(p.q90-p.q10)}
function rawToNorm(i,v){const p=B.parameters[i];return clamp((v-p.q10)/(p.q90-p.q10),0,1)}
function predictOne(model,x){let z=[];for(let i=0;i<x.length;i++){let v=Number.isFinite(x[i])?x[i]:model.median[i];if(model.keep[i])z.push(v)}let s=model.intercept;for(let i=0;i<z.length;i++)s+=((z[i]-model.mean[i])/model.scale[i])*model.coef[i];return s}
function nearestFill(rep){const zr=rep.map((v,i)=>(v-B.rep_mean[i])/B.rep_scale[i]);let ds=B.training_rep9.map((r,k)=>({k,d:Math.sqrt(r.reduce((s,v,i)=>s+((v-B.rep_mean[i])/B.rep_scale[i]-zr[i])**2,0))})).sort((a,b)=>a.d-b.d);let nn=ds.slice(0,7),w=nn.map(x=>1/(x.d+.25)**2),ws=w.reduce((a,b)=>a+b,0),full=B.training_full45[0].map((_,j)=>nn.reduce((s,n,i)=>s+B.training_full45[n.k][j]*w[i]/ws,0));B.representative_features.forEach((f,i)=>full[B.process_feature_names.indexOf(f)]=rep[i]);return{full,d:ds[0].d}}
let baseline=null,currentPred=null;
function drawWafer(pred){const canvas=$('#wafer'),css=360,dpr=Math.min(devicePixelRatio||1,2);canvas.width=css*dpr;canvas.height=css*dpr;const c=canvas.getContext('2d');c.scale(dpr,dpr);c.clearRect(0,0,css,css);const cx=180,cy=180,R=156,mean=pred.si_mean,edge=pred.edge_center,amp=Math.max(.15,mean*pred.si_cv/100*.75);const img=c.createImageData(css*dpr,css*dpr),data=img.data;function color(t){t=clamp(t,0,1);const stops=[[24,56,163],[43,119,229],[66,209,208],[255,226,122],[240,100,68]],u=t*(stops.length-1),i=Math.min(stops.length-2,Math.floor(u)),f=u-i;return stops[i].map((v,k)=>Math.round(v+(stops[i+1][k]-v)*f))}let vals=[];for(let y=0;y<css*dpr;y++){for(let x=0;x<css*dpr;x++){let xx=x/dpr,yy=y/dpr,dx=(xx-cx)/R,dy=(yy-cy)/R,r=Math.sqrt(dx*dx+dy*dy),idx=(y*css*dpr+x)*4;if(r<=1){let th=Math.atan2(dy,dx),v=mean+edge*(r*r-.52)+amp*(.24*Math.sin(3*th)*(r**1.5)+.12*Math.cos(2*th+1.1)*r);vals.push(v);let t=.5+(v-mean)/(Math.max(3.5,Math.abs(edge)*1.15+amp)*2),co=color(t);data[idx]=co[0];data[idx+1]=co[1];data[idx+2]=co[2];data[idx+3]=255}else data[idx+3]=0}}c.putImageData(img,0,0);c.save();c.beginPath();c.arc(cx,cy,R,0,Math.PI*2);c.strokeStyle='#fff';c.lineWidth=5;c.stroke();c.beginPath();c.moveTo(cx-15,cy-R+3);c.lineTo(cx+15,cy-R+3);c.strokeStyle='#10233d';c.lineWidth=6;c.stroke();c.restore();c.fillStyle='#fff';c.textAlign='center';c.font='800 23px Segoe UI';c.fillText(fmt(mean,3)+' µm',cx,cy-5);c.font='12px Segoe UI';c.fillText('예측 평균 깊이',cx,cy+18);$('#mapCenter').textContent='중앙 쪽 '+fmt(mean-edge*.52,2)+' µm';$('#mapEdge').textContent='가장자리 쪽 '+fmt(mean+edge*.48,2)+' µm'}
function run(){const rep=B.parameters.map((_,i)=>rawValue(i)),fill=nearestFill(rep),ord=+$('#order').value,x=[ord,...fill.full],pred={};Object.keys(B.models).forEach(t=>pred[t]=predictOne(B.models[t],x));currentPred=pred;if(!baseline)baseline={...pred};B.parameters.forEach((p,i)=>{const n=+$('#p'+i).value;$('#n'+i).textContent=fmt(n,2);$('#dial'+i).style.setProperty('--norm',(n*100)+'%')});$('#orderOut').textContent=ord+'번째';Object.entries(pred).forEach(([t,v])=>{const m=B.targets[t],el=document.querySelector(`[data-out="${t}"]`),dec=t==='selectivity'?1:3;el.querySelector('.value').textContent=fmt(v,dec)+' '+m.unit;el.querySelector('.range span').style.setProperty('--pos',clamp((v-m.q10)/(m.q90-m.q10)*100,0,100)+'%');el.querySelector('.meta').textContent=`관측 10–90% ${fmt(m.q10,dec)}–${fmt(m.q90,dec)} · MAE ${fmt(m.mae,dec)}`});const q=B.nearest_neighbor_distance_q50_q90;let label,color,pct;if(fill.d<=q[0]){label='과거 데이터와 매우 비슷함';color='var(--green)';pct=30}else if(fill.d<=q[1]){label='과거 데이터 범위 안쪽';color='var(--amber)';pct=65}else{label='과거에 드문 조합';color='var(--red)';pct=95}$('#supportText').textContent=label;$('#supportDistance').textContent='거리 '+fmt(fill.d,2);$('#supportBar').style.setProperty('--support',pct+'%');$('#supportBar').style.setProperty('--support-color',color);drawWafer(pred)}
function preset(kind,button){let idx=null;if(kind==='deep')idx=B.training_outputs.map((r,k)=>({v:r[0],k})).sort((a,b)=>b.v-a.v).slice(0,18).map(x=>x.k);if(kind==='shallow')idx=B.training_outputs.map((r,k)=>({v:r[0],k})).sort((a,b)=>a.v-b.v).slice(0,18).map(x=>x.k);B.parameters.forEach((p,i)=>{let raw=p.median;if(idx){let arr=idx.map(k=>B.training_rep9[k][i]).sort((a,b)=>a-b);raw=arr[Math.floor(arr.length/2)]}$('#p'+i).value=rawToNorm(i,raw)});$$('.preset-card').forEach(x=>x.classList.toggle('active',x===button));$('#scenarioText').textContent=kind==='median'?'88장 전체에서 각 센서의 중앙값을 모은 비교 기준입니다. 실제 한 장을 복사한 값은 아닙니다.':kind==='deep'?'실제로 깊게 측정된 상위 20% 웨이퍼들의 센서 중앙값입니다. 깊게 만드는 최적 레시피라는 뜻은 아닙니다.':'실제로 얕게 측정된 하위 20% 웨이퍼들의 센서 중앙값입니다. 얕게 만드는 원인이라는 뜻은 아닙니다.';run()}
$$('.tab').forEach(b=>b.onclick=()=>{$$('.tab').forEach(x=>x.classList.toggle('active',x===b));$$('.panel').forEach(p=>p.classList.toggle('active',p.id===b.dataset.tab));if(b.dataset.tab==='simulate'&&currentPred)drawWafer(currentPred)});
$$('input[type=range]').forEach(x=>x.addEventListener('input',run));$$('.preset-card').forEach(x=>x.onclick=()=>preset(x.dataset.preset,x));
$$('.info-btn').forEach(b=>b.onclick=()=>{const el=$('#info'+b.dataset.info),open=el.hidden;el.hidden=!open;b.setAttribute('aria-expanded',open)});
function showQuality(){const m=$('#qualityModal');m.hidden=false}$$('.quality').forEach(b=>b.onclick=showQuality);$('#qualityHelp').onclick=showQuality;$('#closeModal').onclick=()=>$('#qualityModal').hidden=true;$('#qualityModal').onclick=e=>{if(e.target.id==='qualityModal')e.currentTarget.hidden=true};
const equipData={source:['↩','Source RF 반사 전력','상부 코일이 플라즈마를 만드는 계통입니다. 반사 전력이 높으면 공급 전력 일부가 되돌아와 결합 상태가 좋지 않을 가능성이 있습니다.'],gas:['✦','C4F8·SF6 가스','C4F8은 측벽 보호막을 만들고 SF6는 F 라디칼로 Si를 제거합니다. 두 단계가 6초 주기로 반복됩니다.'],pressure:['◎','챔버 압력','입자 충돌과 체류시간을 바꿉니다. 높고 낮음의 단순 직선 관계보다 적정 영역이 중요합니다.'],plasma:['✧','플라즈마','중성 가스를 라디칼과 이온으로 분해한 반응 공간입니다. Source RF가 생성량을 주로 좌우합니다.'],platen:['↯','Platen RF·DC bias','웨이퍼 아래 전극에서 이온을 아래 방향으로 가속합니다. 깊이와 수직성뿐 아니라 손상에도 영향을 줍니다.'],match:['⌁','RF 매칭 회로','플라즈마의 전기적 부하가 변할 때 전력이 잘 전달되도록 커패시터 위치를 자동 조정합니다.'],heater:['≈','Heater2·온도 안정도','표면 반응과 폴리머 형성은 온도에 민감합니다. 여기서는 평균보다 공정 중 온도 흔들림을 사용합니다.'],diagnostic:['◇','mori 내부 전류','장비 고유 진단 채널입니다. 정의가 없으므로 원인 변수로 단정하지 않고 상태 표시로만 사용합니다.'],exhaust:['⇣','배기·압력 제어','펌프와 밸브가 가스를 배출하고 챔버 압력을 유지합니다. ForeLinePressure는 간접값이라 최종 9개에서는 제외했습니다.']};
function equip(key){const d=equipData[key];$$('.hot').forEach(x=>x.classList.toggle('active',x.dataset.equip===key));$('#equipIcon').textContent=d[0];$('#equipTitle').textContent=d[1];$('#equipText').textContent=d[2]}$$('.hot').forEach(x=>{x.onclick=()=>equip(x.dataset.equip);x.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')equip(x.dataset.equip)}});equip('plasma');
baseline=null;run();baseline={...currentPred};
"""

